@js:
var out = '';
try {
  var raw = String(result || '');
  var body = raw
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|h[1-6]|tr|td)>/gi, '\n')
    .replace(/<[^>]+>/g, '');
  body = body
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/[ \t\u3000]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
  if (body.length > 12000) body = body.substring(0, 12000);
  if (body.length > 20) {
    var lines = body.split('\n');
    var parts = [];
    for (var i = 0; i < lines.length; i++) {
      var t = String(lines[i]).trim();
      if (t.length > 0) parts.push('<p>' + t + '</p>');
    }
    if (parts.length > 0) out = parts.join('');
  }
} catch (e) {}
if (!out) {
  out = '<p>这个站只提供资源接口，页面里没有可直接抓取的正文。</p><p>想看原网页可以点右上角菜单里的「浏览器打开」。</p>';
}
out;

